"""The finder's only tool: locate, lookup or read, with a hard budget of 4 calls per task.

Generated by scripts/build_finder_tool.py; edit that or swe-tools' scripts, not this file.
The count lives in <workspace>/.git, so it is per task and never shows up in the diff.
Once the budget is used up the script does nothing and tells the finder to write its brief.
"""
import argparse
import contextlib
import io
import os
import sys
from pathlib import Path

BUDGET = 4
LOCATE_SRC = '"""Rank the source files and definitions most likely to need the fix.\n\nUsage: locate.py --query "<issue text or key terms>" [--top 8]\n\nPulls identifiers, dotted names, file paths and quoted strings out of the\nquery, searches the repository\'s non-test Python files for them, and prints the\nbest-scoring files with the matching definitions and lines.\n"""\nimport argparse\nimport math\nimport os\nimport re\nimport sys\nfrom collections import Counter, defaultdict\nfrom pathlib import Path\n\nSTOP = set(\'\'\'\na an and are as at be but by can could do does for from has have how i if in into is it its\nmay not of on or should so than that the then there these this to use used using was we when\nwhere which while will with would you your error issue bug fix expected actual behavior\nversion python true false none self return raise class def import value values type types\ndefault example code test tests case get set new also like just only one same file line\n\'\'\'.split())\nSKIP_DIRS = {\'.git\', \'tests\', \'test\', \'testing\', \'docs\', \'build\', \'dist\',\n             \'__pycache__\', \'.venv\', \'venv\', \'node_modules\', \'scripts\', \'benchmarks\', \'examples\'}\nDEF_RE = re.compile(r\'^\\s*(?:async\\s+)?(def|class)\\s+([A-Za-z_]\\w*)\')\n\n\ndef workspace() -> Path:\n    for cand in (Path(\'/workspace\'), Path(os.environ.get(\'PWD\', \'.\'))):\n        if (cand / \'.git\').exists():\n            return cand\n    return Path(os.environ.get(\'PWD\', \'.\'))\n\n\ndef terms_from(query: str) -> Counter:\n    terms: Counter = Counter()\n    for q in re.findall(r\'["\\\'`]([^"\\\'`\\n]{3,80})["\\\'`]\', query):\n        terms[q.strip()] += 3  # quoted strings: error messages, literals\n    for dotted in re.findall(r\'\\b[A-Za-z_]\\w*(?:\\.[A-Za-z_]\\w*)+\\b\', query):\n        for part in dotted.split(\'.\'):\n            if len(part) > 2 and part.lower() not in STOP:\n                terms[part] += 2\n        terms[dotted] += 2\n    for path in re.findall(r\'[\\w/]+\\.py\\b\', query):\n        terms[Path(path).stem] += 3\n    for word in re.findall(r\'\\b[A-Za-z_][A-Za-z0-9_]{2,}\\b\', query):\n        if word.lower() in STOP:\n            continue\n        code_like = \'_\' in word or any(c.isupper() for c in word[1:]) or word[0].isupper()\n        terms[word] += 2 if code_like else 1\n    return terms\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'--query\', required=True)\n    ap.add_argument(\'--top\', type=int, default=8)\n    a = ap.parse_args()\n\n    root = workspace()\n    terms = terms_from(a.query)\n    if not terms:\n        print(\'No searchable terms in query.\')\n        return\n    files = []\n    for dirpath, dirnames, filenames in os.walk(root):\n        dirnames[:] = [d for d in dirnames if d not in SKIP_DIRS and not d.startswith(\'.\')]\n        for name in filenames:\n            if name.endswith(\'.py\') and not name.startswith((\'test_\', \'conftest\', \'.\')):\n                files.append(Path(dirpath) / name)\n\n    doc_freq: Counter = Counter()\n    contents = {}\n    for f in files:\n        try:\n            text = f.read_text(encoding=\'utf-8\', errors=\'replace\')\n        except OSError:\n            continue\n        contents[f] = text\n        for t in terms:\n            if t in text:\n                doc_freq[t] += 1\n    n = max(1, len(contents))\n\n    scores = {}\n    hits = defaultdict(list)\n    for f, text in contents.items():\n        score = 0.0\n        rel = str(f.relative_to(root))\n        lines = text.splitlines()\n        defs = {m.group(2): i for i, line in enumerate(lines) if (m := DEF_RE.match(line))}\n        for t, weight in terms.items():\n            if t not in text:\n                continue\n            idf = math.log(1 + n / doc_freq[t])\n            score += weight * idf * min(3, text.count(t)) ** 0.5\n            if t in defs:  # the term is defined here\n                score += 3 * weight * idf\n                hits[f].append((defs[t] + 1, lines[defs[t]].strip()))\n            if t.lower() == f.stem.lower() or t in rel.replace(\'/\', \'.\'):\n                score += 2 * weight * idf\n        if score:\n            # docs examples are sometimes the fix site, but rarely the first place to look\n            scores[f] = score * (0.6 if rel.startswith(\'docs_src/\') else 1.0)\n\n    ranked = sorted(scores, key=scores.get, reverse=True)[: a.top]\n    if not ranked:\n        print(\'No matches. Try different terms (symbol names, error text).\')\n        return\n    for f in ranked:\n        print(f\'{f.relative_to(root)}  (score {scores[f]:.1f})\')\n        for lineno, line in sorted(set(hits[f]))[:6]:\n            print(f\'    {lineno}: {line[:120]}\')\n    print(\'\\nRead the top files with read_file before editing; scores are lexical, not certain.\')\n\n\nif __name__ == \'__main__\':\n    try:\n        main()\n    except Exception as exc:  # never crash the agent\'s turn\n        print(f\'locate.py failed: {exc}\', file=sys.stderr)\n'
LOOKUP_SRC = '"""Answer several code lookups in one call.\n\nUsage: lookup.py --names "Console.print, soft_wrap, \'some error text\'" [--file rich/console.py]\n\nFor each comma-separated name prints:\n- every definition (def / class / NAME = ...) with its body, numbered, up to 40 lines;\n- up to 6 places that use it (file:line: code).\nA quoted entry is searched as literal text and shown with 2 lines of context.\nTest files are skipped. --file restricts the search to one file or directory.\nOutput stays under ~4,500 characters so nothing is cut off.\n"""\nimport argparse\nimport os\nimport re\nfrom pathlib import Path\n\nSKIP_DIRS = {\'.git\', \'tests\', \'test\', \'testing\', \'build\', \'dist\', \'__pycache__\',\n             \'.venv\', \'venv\', \'node_modules\', \'examples\', \'benchmarks\'}\nBUDGET = 4500\nBODY_LINES = 40\nUSES = 6\n\n\ndef workspace() -> Path:\n    for cand in (Path(\'/workspace\'), Path(os.environ.get(\'PWD\', \'.\'))):\n        if (cand / \'.git\').exists():\n            return cand\n    return Path(os.environ.get(\'PWD\', \'.\'))\n\n\ndef source_files(root: Path, only: str | None):\n    base = root / only if only else root\n    if base.is_file():\n        yield base\n        return\n    for dirpath, dirnames, filenames in os.walk(base):\n        dirnames[:] = sorted(d for d in dirnames if d not in SKIP_DIRS and not d.startswith(\'.\'))\n        for name in sorted(filenames):\n            if name.endswith(\'.py\') and not name.startswith((\'test_\', \'conftest\', \'.\')) \\\n                    and not name.endswith(\'_test.py\'):\n                yield Path(dirpath) / name\n\n\ndef block_end(lines: list[str], start: int) -> int:\n    """Index after the indented block that starts at lines[start]."""\n    indent = len(lines[start]) - len(lines[start].lstrip())\n    i = start + 1\n    # Skip a multi-line signature: continue until the line ending with \':\'.\n    while i < len(lines) and not lines[i - 1].rstrip().endswith(\':\') and i - start < 15:\n        i += 1\n    while i < len(lines):\n        s = lines[i]\n        if s.strip() and len(s) - len(s.lstrip()) <= indent and not s.lstrip().startswith((\')\', \']\', \'}\')):\n            break\n        i += 1\n    return i\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument(\'--names\', required=True)\n    ap.add_argument(\'--file\')\n    a = ap.parse_args()\n    root = workspace()\n    texts = {}\n    for f in source_files(root, a.file):\n        try:\n            texts[f.relative_to(root)] = f.read_text(encoding=\'utf-8\', errors=\'replace\').splitlines()\n        except OSError:\n            pass\n\n    entries = [e.strip() for e in a.names.split(\',\') if e.strip()]\n    per_entry = max(600, BUDGET // max(1, len(entries)))\n    body_lines = BODY_LINES if len(entries) <= 2 else 25\n    out = []\n    for entry in entries:\n        chunk = []\n        literal = entry[0] in \'\\\'"`\' and entry[-1] == entry[0] and len(entry) > 2\n        if literal:\n            needle = entry[1:-1]\n            chunk.append(f\'== text {needle!r}\')\n            hits = 0\n            for path, lines in texts.items():\n                for i, line in enumerate(lines):\n                    if needle in line:\n                        hits += 1\n                        if hits <= 5:\n                            lo, hi = max(0, i - 2), min(len(lines), i + 3)\n                            chunk.append(f\'{path}:{i + 1}\')\n                            chunk += [f\'{j + 1:>5} {lines[j]}\' for j in range(lo, hi)]\n            if hits > 5:\n                chunk.append(f\'... {hits - 5} more matches\')\n            if not hits:\n                chunk.append(\'not found\')\n        else:\n            name = entry.split(\'.\')[-1]\n            owner = entry.split(\'.\')[-2] if \'.\' in entry else None\n            def_re = re.compile(rf\'^\\s*(?:async\\s+)?(?:def|class)\\s+{re.escape(name)}\\b|^\\s*{re.escape(name)}\\s*(?::[^=]*)?=[^=].*[^,(]$\')\n            # Attribute access for Owner.name, else the bare word; prose in comments is skipped.\n            use_re = re.compile(rf\'\\.{re.escape(name)}\\b\' if owner else rf\'\\b{re.escape(name)}\\b\')\n            chunk.append(f\'== {entry}\')\n            defs = uses = 0\n            use_lines = []\n            for path, lines in texts.items():\n                for i, line in enumerate(lines):\n                    if def_re.search(line):\n                        if owner:  # only the definition inside the named class or module\n                            if line.startswith((\' \', \'\\t\')):\n                                cls = next((lines[k] for k in range(i, -1, -1)\n                                            if lines[k].startswith(\'class \')), \'\')\n                                if not re.match(rf\'class\\s+{re.escape(owner)}\\b\', cls):\n                                    continue\n                            elif path.stem != owner:\n                                continue\n                        defs += 1\n                        if defs > 3:\n                            continue\n                        end = block_end(lines, i) if line.lstrip().startswith((\'def\', \'class\', \'async\')) else i + 1\n                        shown = min(end, i + body_lines)\n                        chunk.append(f\'{path}:{i + 1}-{end} (definition)\')\n                        chunk += [f\'{j + 1:>5} {lines[j]}\' for j in range(i, shown)]\n                        if shown < end:\n                            chunk.append(f\'      ... {end - shown} more lines (read_file {path} {shown + 1}-{end})\')\n                    elif use_re.search(line.split(\'#\', 1)[0]) and not line.lstrip().startswith((\'"\', "\'")):\n                        uses += 1\n                        if len(use_lines) < USES:\n                            use_lines.append(f\'  {path}:{i + 1}: {line.strip()[:110]}\')\n            if not defs:\n                chunk.append(\'no definition found\')\n            if use_lines:  # keep uses near the top so a long body cannot push them out\n                chunk[1:1] = [f\'used in {uses} places, e.g.:\'] + use_lines\n        text = \'\\n\'.join(chunk)\n        if len(text) > per_entry:\n            text = text[:per_entry] + \'\\n... (cut; narrow with --file or a more specific name)\'\n        out.append(text)\n    print(\'\\n\\n\'.join(out))\n\n\nif __name__ == \'__main__\':\n    main()\n'
STOP = ('INVESTIGATION BUDGET USED UP. Do not call any tool again. '
        'Reply now with the brief (ISSUE ASKS, FILES, ROOT CAUSE, CHANGE, CHECK) from what you have seen.')


def workspace() -> Path:
    for cand in (Path('/workspace'), Path(os.environ.get('PWD', '.')), Path.cwd()):
        if (cand / '.git').exists():
            return cand
    return Path.cwd()


def run_embedded(src: str, argv: list[str]) -> str:
    buf = io.StringIO()
    old = sys.argv
    sys.argv = ['tool'] + argv
    try:
        with contextlib.redirect_stdout(buf):
            exec(compile(src, 'tool.py', 'exec'), {'__name__': '__main__'})
    except SystemExit:
        pass
    except Exception as e:  # report instead of crashing the call
        buf.write(f'error: {e!r}')
    finally:
        sys.argv = old
    return buf.getvalue()


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument('--mode', default='lookup')
    ap.add_argument('--query', default='')
    ap.add_argument('--names', default='')
    ap.add_argument('--file', default='')
    ap.add_argument('--start', type=int, default=1)
    ap.add_argument('--end', type=int, default=0)
    a, _ = ap.parse_known_args()
    ws = workspace()
    counter = ws / '.git' / 'finder_calls'
    try:
        used = int(counter.read_text()) if counter.exists() else 0
    except (OSError, ValueError):
        used = 0
    if used >= BUDGET:
        print(STOP)
        return
    try:
        counter.write_text(str(used + 1))
    except OSError:
        pass
    os.chdir(ws)
    mode = a.mode.lower()
    if mode == 'locate':
        out = run_embedded(LOCATE_SRC, ['--query', a.query or a.names])
    elif mode == 'read':
        path = ws / a.file
        lines = path.read_text(encoding='utf-8', errors='replace').splitlines() if path.is_file() else []
        start = max(1, a.start)
        end = min(len(lines), a.end if a.end >= start else start + 79, start + 79)
        out = '\n'.join(f'{i}: {lines[i - 1]}' for i in range(start, end + 1)) or f'No such file or range: {a.file}'
    else:
        out = run_embedded(LOOKUP_SRC, ['--names', a.names or a.query] + (['--file', a.file] if a.file else []))
    left = BUDGET - used - 1
    print(out.rstrip()[:6000])
    print(f'\n[{left} investigate call(s) left]' if left else '\n' + STOP)


if __name__ == '__main__':
    main()
